@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Import(ResearchFixture.class)
class TeachingWorkflowTest {
 @Autowired TeachingWorkspaceService workspace;@Autowired TeachingAnswerService answers;@Autowired TeachingAccess access;@Autowired TeachingSnapshot snapshots;@Autowired TeachingScoring scoring;@Autowired LocalAnnotationDependencies data;@Autowired UnifiedVersionIdentity identity;@Autowired LocalFixtureLoader fixtures;@Autowired LocalAccountLoader accounts;@Autowired ResearchFixture research;@Autowired FinalReviewRepository finals;@Autowired ObjectMapper mapper;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;
 @SpyBean LocalFinalReviewDependencies deps;@SpyBean TeachingTime clock;@SpyBean TeachingRepository repository;
 Actor creator,teacher,student;String finalId,grantId,courseId,standardId,assignmentId;ObjectNode original;Instant initial=Instant.parse("2026-10-21T10:00:00Z");
 void clean(){for(String t:List.of("workflow_command_history","trial_correction_rounds","trial_segmentation_records","trial_downloads","trial_files","trial_data_events","trial_exports","trial_export_receipts","trial_final_commitments","trial_audit_events","final_review_transitions","final_annotation_versions","adjudication_transitions","adjudication_returned_versions","adjudication_decisions","adjudication_items","adjudication_sessions","annotation_mutation_receipts","snapshot_object_owners","annotation_version_snapshots","annotation_versions","annotation_case_counters","workflow_records"))jdbc.update("DELETE FROM "+t);}
 @BeforeEach void setup()throws Exception{reset(deps,clock,repository);clean();fixtures.run(null);accounts.run(null);doReturn(initial).when(clock).now();creator=identity.authenticate("Bearer dev-creator-li");teacher=identity.actor("2901c453-e8c4-4cfa-948c-7dedb4f2ab8a");student=identity.actor("52b8374c-4ad4-4aca-bed8-1b7bc6687577");original=research.create(true);finalId=original.path("version").path("id").asText();var g=workspace.grantSource(creator,VersionJson.uuid(),mapper.createObjectNode().put("finalVersionId",finalId).put("teacherUserId",teacher.id()));grantId=g.path("id").asText();var b=mapper.createObjectNode().put("name","教学隔离验收").put("className","一班");b.putArray("studentUserIds").add(student.id());var c=workspace.createCourse(teacher,VersionJson.uuid(),b);courseId=c.path("id").asText();workspace.activateCourse(teacher,courseId,VersionJson.uuid(),1,mapper.createObjectNode().put("confirmed",true));var std=workspace.createStandard(teacher,VersionJson.uuid(),mapper.createObjectNode().put("sourceGrantId",grantId).put("name","标准 F1"));standardId=std.path("id").asText();workspace.publishStandard(teacher,standardId,VersionJson.uuid(),1,mapper.createObjectNode().put("reason","核查原文与完整关系图"));assignmentId=assignment("RELATION_GUIDED",2,initial.plusSeconds(300));}
 @AfterEach void after(){reset(deps,clock,repository);clean();}
 String assignment(String mode,int max,Instant open){var a=workspace.createAssignment(teacher,VersionJson.uuid(),mapper.createObjectNode().put("name","独立作答").put("courseId",courseId).put("standardId",standardId).put("exerciseMode",mode).put("exerciseType","GRAPH_COMPARE").put("dueAt",initial.plusSeconds(3600).toString()));workspace.publishAssignment(teacher,a.path("id").asText(),VersionJson.uuid(),1,mapper.createObjectNode().put("maxAttempts",max).put("answerOpensAt",open.toString()));return a.path("id").asText();}
 ObjectNode attempt(){return answers.createAttempt(student,assignmentId,VersionJson.uuid(),mapper.createObjectNode().put("reason","开始独立作答"));}
 ObjectNode body(boolean correct){var ds=workspace.dataset(data.read("teachingAssignment",assignmentId));var b=mapper.createObjectNode();b.putArray("elements");var list=b.putArray("relations");for(var r:ds.path("relations")){var n=list.addObject().put("ref",VersionJson.uuid()).put("code",correct?r.path("relationCode").asText():"A");var parts=n.putArray("participants");for(var p:TeachingSnapshot.rows(ds,"participants").stream().sorted(Comparator.comparingInt(x->x.path("ordinal").asInt())).toList())if(p.path("relationId").equals(r.path("id")))parts.addObject().put("role",p.path("role").asText()).put("targetKind","ELEMENT").put("targetId",p.path("targetId").asText()).putNull("targetRef");}return b;}
 String complete(boolean correct){var a=attempt();String id=a.path("id").asText();var saved=answers.save(student,id,VersionJson.uuid(),1,body(correct));return answers.submit(student,id,VersionJson.uuid(),saved.path("recordVersion").asInt(),mapper.createObjectNode().put("confirmed",true)).path("resultId").asText();}
 @Test void assignmentStoresExecutableScoringVersion(){assertThat(data.read("teachingAssignment",assignmentId).path("scoringRuleVersion").asText()).isEqualTo(TeachingScoring.version());}
 @Test void standardParticipantArrayOrderDoesNotChangeDirection(){var ds=workspace.dataset(data.read("teachingAssignment",assignmentId));var rows=new ArrayList<JsonNode>();ds.path("participants").forEach(rows::add);rows.sort(Comparator.comparingInt(x->-x.path("ordinal").asInt()));var shuffled=ds.putArray("participants");rows.forEach(shuffled::add);var templates=scoring.templates(ds);for(var r:templates)assertThat(r.participants()).isSortedAccordingTo(Comparator.comparingInt(com.argument.teaching.dto.TemplateParticipant::ordinal));assertThat(scoring.score(VersionJson.uuid(),"GRAPH_COMPARE",ds,templates).path("relationSpecialistScore").asInt()).isEqualTo(100);}
 @Test void serverWithholdsScoresStandardsGraphsAndFeedbackUntilSubmissionAndOpening(){var c=answers.studentContext(student,assignmentId);assertThat(c.path("material").has("givenElements")).isTrue();assertThat(c.toString()).doesNotContain("standardId","standardDigest","relations","datasetDigest");String id=complete(true);answers.feedback(teacher,id,VersionJson.uuid(),mapper.createObjectNode().put("comment","先检查支持方向").set("itemFeedback",mapper.createArrayNode()));var held=answers.result(student,id);assertThat(held.path("scoreAvailability").asText()).isEqualTo("HELD");assertThat(held.toString()).doesNotContain("grading","standardSnapshot","specialist","standardAnswer","teacherFeedback","gradeDigest","sourceFinalVersionId");doReturn(initial.plusSeconds(301)).when(clock).now();var open=answers.result(student,id);assertThat(open.path("scoreAvailability").asText()).isEqualTo("AVAILABLE");assertThat(open.path("grading").path("relationSpecialistScore").asInt()).isEqualTo(100);assertThat(open.path("totalScore").isNull()).isTrue();assertThat(open.path("teacherFeedback")).hasSize(1);assertThat(answers.result(teacher,id).path("grading")).isEqualTo(open.path("grading"));}
 @Test void fullCaseMaterialDoesNotLeakStandardBoundariesOrTypes(){assignmentId=assignment("FULL_CASE",1,initial.minusSeconds(1));var c=answers.studentContext(student,assignmentId);assertThat(c.path("material").has("givenElements")).isFalse();assertThat(c.path("material").fieldNames()).toIterable().containsExactlyInAnyOrder("scopeText","offsetBase","labels");assertThat(c.path("draft").isNull()).isTrue();assertThat(c.toString()).doesNotContain("standardId","standardSnapshot","startOffset","relationSpecialistScore");}
 @Test void fullCaseSubmissionKeepsUnknownTotalNullAndRequiresCompleteCoverage(){assignmentId=assignment("FULL_CASE",1,initial.minusSeconds(1));var a=attempt();String id=a.path("id").asText();var ds=workspace.dataset(data.read("teachingAssignment",assignmentId));int left=ds.path("scope").path("startOffset").asInt(),right=ds.path("scope").path("endOffset").asInt();var b=mapper.createObjectNode();b.putArray("elements").addObject().put("clientKey",VersionJson.uuid()).put("startOffset",left).put("endOffset",right-1).put("labelCode","GM-L");b.putArray("relations");answers.save(student,id,VersionJson.uuid(),1,b);assertThatThrownBy(()->answers.submit(student,id,VersionJson.uuid(),2,mapper.createObjectNode().put("confirmed",true))).hasMessageContaining("覆盖");((ObjectNode)b.path("elements").get(0)).put("endOffset",right);var s=answers.save(student,id,VersionJson.uuid(),2,b);String result=answers.submit(student,id,VersionJson.uuid(),s.path("recordVersion").asInt(),mapper.createObjectNode().put("confirmed",true)).path("resultId").asText();var grade=answers.result(student,result).path("grading");assertThat(grade.path("totalScore").isNull()).isTrue();assertThat(grade.path("relationSpecialistScore").isNull()).isTrue();assertThat(grade.path("scoreStatus").asText()).contains("PENDING");}
 @Test void oldAttemptsAndScoresStayFrozenAfterStandardRevision(){String first=complete(false);var before=answers.result(teacher,first);var assignment=data.read("teachingAssignment",assignmentId);var oldStandard=workspace.standard(teacher,standardId);var next=workspace.reviseStandard(teacher,standardId,VersionJson.uuid(),mapper.createObjectNode().put("sourceGrantId",grantId).put("reason","追加标准版本用于下次作业"));workspace.publishStandard(teacher,next.path("id").asText(),VersionJson.uuid(),1,mapper.createObjectNode().put("reason","二版核查"));String second=complete(true);assertThat(answers.result(teacher,first)).isEqualTo(before);assertThat(data.read("teachingAssignment",assignmentId)).isEqualTo(assignment);assertThat(workspace.standard(teacher,standardId)).isEqualTo(oldStandard);assertThat(answers.result(teacher,second).path("grading").path("relationSpecialistScore").asInt()).isEqualTo(100);assertThat(answers.result(teacher,first).path("grading").path("relationSpecialistScore").asInt()).isLessThan(100);assertThat(data.find("teachingAttemptSnapshot",null,null)).hasSize(2);assertThat(finals.snapshot(finalId)).isEqualTo(original);}
 @Test void repeatedReadsAreReadOnlyAndDoNotCreateDrafts(){int before=data.find("teachingEvent",null,null).size();var first=answers.studentContext(student,assignmentId);assertThat(answers.studentContext(student,assignmentId)).isEqualTo(first);assertThat(data.find("teachingAnswer",null,null)).isEmpty();assertThat(data.find("teachingEvent",null,null)).hasSize(before);}
 @Test void submissionsAreImmutableAndIdempotentAndCannotExceedAttempts(){assignmentId=assignment("RELATION_GUIDED",1,initial.plusSeconds(300));String key=VersionJson.uuid();var a=answers.createAttempt(student,assignmentId,key,mapper.createObjectNode().put("reason","开始"));assertThat(answers.createAttempt(student,assignmentId,key,mapper.createObjectNode().put("reason","开始"))).isEqualTo(a);String id=a.path("id").asText();answers.save(student,id,VersionJson.uuid(),1,body(true));String submitKey=VersionJson.uuid();var b=mapper.createObjectNode().put("confirmed",true);var response=answers.submit(student,id,submitKey,2,b);assertThat(answers.submit(student,id,submitKey,2,b)).isEqualTo(response);assertThatThrownBy(()->answers.save(student,id,VersionJson.uuid(),3,body(false))).hasMessageContaining("不可覆盖");assertThatThrownBy(this::attempt).hasMessageContaining("次数");assertThat(data.find("teachingResult",null,null)).hasSize(1);}
 @Test void deadlineAndStaleVersionAreEnforced(){var a=attempt();String id=a.path("id").asText();answers.save(student,id,VersionJson.uuid(),1,body(true));assertThatThrownBy(()->answers.save(student,id,VersionJson.uuid(),1,body(false))).hasMessageContaining("刷新");doReturn(initial.plusSeconds(3601)).when(clock).now();assertThatThrownBy(()->answers.submit(student,id,VersionJson.uuid(),2,mapper.createObjectNode().put("confirmed",true))).hasMessageContaining("截止");assertThat(data.find("teachingResult",null,null)).isEmpty();}
 @Test void courseAndResultScopeCannotBeBypassedByAdminOrAnotherStudent(){String id=complete(true);var admin=identity.authenticate("Bearer dev-admin-wang");assertThatThrownBy(()->workspace.overview(admin)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->workspace.standard(student,standardId)).isInstanceOf(BusinessException.class);var clone=data.read("user",student.id()).deepCopy();String uid=VersionJson.uuid();clone.put("id",uid);repository.insert("user",clone);var other=identity.actor(uid);String cls=data.read("teachingCourse",courseId).path("classId").asText();var member=mapper.createObjectNode();VersionJson.stamp(member,teacher.id(),VersionJson.now());member.put("classId",cls).put("studentUserId",uid).put("status","ACTIVE");repository.insert("teachingMembership",member);assertThat(answers.studentContext(other,assignmentId).path("attempts")).isEmpty();assertThatThrownBy(()->answers.result(other,id)).hasMessageContaining("本人结果");assertThat(answers.results(other).path("items")).isEmpty();}
 @Test void memberRevocationImmediatelyBlocksOldResults(){String id=complete(true);var m=data.find("teachingMembership","studentUserId",student.id()).get(0);workspace.deactivateMember(teacher,m.path("id").asText(),VersionJson.uuid(),1,mapper.createObjectNode().put("reason","撤销班级成员"));assertThatThrownBy(()->answers.result(student,id)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->answers.studentContext(student,assignmentId)).isInstanceOf(BusinessException.class);assertThat(answers.result(teacher,id).path("grading").isObject()).isTrue();}
 @Test void sourceGrantIsRequiredAndRevocationBlocksNewStandardsButNotFrozenPublishedAssignments(){var another=data.read("user",teacher.id()).deepCopy();String uid=VersionJson.uuid();another.put("id",uid);repository.insert("user",another);var otherTeacher=identity.actor(uid);assertThatThrownBy(()->workspace.createStandard(otherTeacher,VersionJson.uuid(),mapper.createObjectNode().put("sourceGrantId",grantId).put("name","越权标准"))).isInstanceOf(BusinessException.class);var g=data.read("teachingSourceGrant",grantId);workspace.revokeSource(creator,grantId,VersionJson.uuid(),g.path("recordVersion").asInt(),mapper.createObjectNode().put("reason","不再授权新教学使用"));assertThatThrownBy(()->workspace.createStandard(teacher,VersionJson.uuid(),mapper.createObjectNode().put("sourceGrantId",grantId).put("name","新标准"))).isInstanceOf(BusinessException.class);assertThat(answers.studentContext(student,assignmentId).path("material").path("scopeText").asText()).isNotBlank();assertThat(finals.snapshot(finalId)).isEqualTo(original);}
 @Test void auditFailureRollsBackSubmissionScoreAndAttemptSnapshot(){var a=attempt();String id=a.path("id").asText();answers.save(student,id,VersionJson.uuid(),1,body(true));doThrow(new BusinessException(ErrorCode.CONFLICT,"audit failure")).when(repository).event(org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.eq("SUBMIT_ANSWER:"+id),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyString());assertThatThrownBy(()->answers.submit(student,id,VersionJson.uuid(),2,mapper.createObjectNode().put("confirmed",true))).isInstanceOf(BusinessException.class);assertThat(data.read("teachingAnswer",id).path("status").asText()).isEqualTo("DRAFT");assertThat(data.find("teachingResult",null,null)).isEmpty();assertThat(data.find("teachingGradeSnapshot",null,null)).isEmpty();assertThat(data.find("teachingAttemptSnapshot",null,null)).isEmpty();}
 @Test void concurrentSubmissionCreatesOneResult()throws Exception{var a=attempt();String id=a.path("id").asText();answers.save(student,id,VersionJson.uuid(),1,body(true));var pool=Executors.newFixedThreadPool(2);try{var tasks=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{try{answers.submit(student,id,VersionJson.uuid(),2,mapper.createObjectNode().put("confirmed",true));return true;}catch(BusinessException e){return false;}}));int success=0;for(var f:tasks)if(f.get(20,TimeUnit.SECONDS))success++;assertThat(success).isEqualTo(1);}finally{pool.shutdownNow();}assertThat(data.find("teachingResult",null,null)).hasSize(1);}
 @Test void forgedGivenElementsAndCrossScopeRelationsAreRejected(){var a=attempt();String id=a.path("id").asText();var b=body(true);b.withArray("elements").addObject().put("clientKey",VersionJson.uuid());assertThatThrownBy(()->answers.save(student,id,VersionJson.uuid(),1,b)).hasMessageContaining("给定命题");var r=body(true);((ObjectNode)r.path("relations").get(0).path("participants").get(0)).put("targetId",VersionJson.uuid());assertThatThrownBy(()->answers.save(student,id,VersionJson.uuid(),1,r)).isInstanceOf(BusinessException.class);assertThat(data.read("teachingAnswer",id).path("recordVersion").asInt()).isEqualTo(1);}
 @Test void feedbackIsAppendOnlyAndCannotTargetForeignObjects(){String id=complete(true);var b=mapper.createObjectNode().put("comment","逐项核查");b.putArray("itemFeedback").addObject().put("targetId",VersionJson.uuid()).put("comment","其他作答");assertThatThrownBy(()->answers.feedback(teacher,id,VersionJson.uuid(),b)).isInstanceOf(BusinessException.class);b.putArray("itemFeedback");answers.feedback(teacher,id,VersionJson.uuid(),b);answers.feedback(teacher,id,VersionJson.uuid(),b.put("comment","追加反馈"));assertThat(data.find("teachingFeedback","resultId",id)).hasSize(2);assertThat(answers.result(student,id).has("teacherFeedback")).isFalse();}
}
